insert into public.recipes
    (slug, title, emoji, description, total_minutes, difficulty, servings, published,
     source_name, source_url, license_name, attribution, modified_from_source)
values
    ('wikibooks_egg_noodles_i', 'Egg Noodles I', '🍜', 'These homemade noodles can be served with a variety of pasta sauces, such as pesto sauce.', 65, 'Easy', 12, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AEgg+Noodles+I&oldid=4501491', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_english_breakfast', 'English Breakfast', '🍞', 'The English breakfast frequently suffers from being prepared badly and with poor quality ingredients. Cooked well, with high quality ingredients, it can be a delicious start to the day. Preparing an English breakfast...', 35, 'Easy', 4, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AEnglish+Breakfast&oldid=4500277', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_snails_with_garlic_butter_escargots_a_la_bourguignonne', 'Snails with Garlic Butter (Escargots à la Bourguignonne)', '🍽️', 'Escargots à la bourguignonne is a French dish of snails with garlic butter.', 45, 'Easy', 4, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ASnails+with+Garlic+Butter+%28Escargots+%C3%A0+la+Bourguignonne%29&oldid=4502308', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_hongshao_rou_red_braised_pork_belly', 'Hongshao Rou (Red Braised Pork Belly)', '🍽️', 'Hongshao rou (lit. red-cooked meat) is a traditional Chinese pork dish. It is a very popular homemade dish, but it is rarely found in Western restaurants. Often a family''s exact recipe is a secret and passed down the...', 75, 'Medium', 4, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AHongshao+Rou+%28Red+Braised+Pork+Belly%29&oldid=4512050', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_danwake', 'Danwake', '🍽️', 'Danwake is a popular Nigerian dish, particularly in the northern regions, made from ground beans (usually black-eyed peas), flour, and spices. It''s often served with a variety of sauces or soups, and it is both...', 45, 'Easy', 3, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ADanwake&oldid=4518751', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_cauliflower_cheese', 'Cauliflower Cheese', '🍞', 'Cauliflower cheese or cauliflower gratin (French: Choufleur au Gratin) is a filling and cheesy dish, great as a side to a roast dinner or any other dish.', 60, 'Easy', 1, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ACauliflower+Cheese&oldid=4514940', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_khara_pongal_rice_and_mung_bean_porridge', 'Khara Pongal (Rice and Mung Bean Porridge)', '🍛', 'Khara pongal is a savoury porridge-like dish that is traditionally prepared in South India for the Makar Sankranti festival that heralds the arrival of summer. The sweet pongal variety differs only in the spices...', 40, 'Medium', 6, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AKhara+Pongal+%28Rice+and+Mung+Bean+Porridge%29&oldid=4615203', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_ghevar_rajasthani_honeycomb_fritter', 'Ghevar (Rajasthani Honeycomb Fritter)', '🍽️', 'Ghevar is an Indian delicacy originally from the state of Rajasthan. It is made with a round mold and has a crispy but porous texture. The following recipe has been entered with inputs from Tarla Dalal recipe book.', 120, 'Medium', 10, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AGhevar+%28Rajasthani+Honeycomb+Fritter%29&oldid=4517736', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_chicken_bacon_broccoli_alfredo_spaghetti', 'Chicken Bacon Broccoli Alfredo Spaghetti', '🍝', 'This chicken bacon broccoli alfredo spaghetti recipe is adapted from the YouTube channel Tasty.', 20, 'Easy', 4, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AChicken+Bacon+Broccoli+Alfredo+Spaghetti&oldid=4522820', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_beanburger', 'Beanburger', '🍳', 'These beanburgers work best in pita breads (crisped up in the oven), with tomato and lettuce. Alternatively, they taste nice with a spicy tomato sauce.', 20, 'Easy', 6, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ABeanburger&oldid=4513928', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_hamburger_fried_rice', 'Hamburger Fried Rice', '🍚', 'A practical recipe for Hamburger Fried Rice, adapted from the Wikibooks Cookbook.', 30, 'Easy', 3, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3AHamburger+Fried+Rice&oldid=4517687', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_baked_ziti', 'Baked Ziti', '🍝', 'Baked ziti is a type of casserole in Italian-American cuisine. It consists primarily of pasta and various cheeses in a tomato-based sauce.', 60, 'Easy', 8, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ABaked+Ziti&oldid=4605227', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_crab_fried_rice', 'Crab Fried Rice', '🍚', 'A practical recipe for Crab Fried Rice, adapted from the Wikibooks Cookbook.', 20, 'Easy', 5, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ACrab+Fried+Rice&oldid=4630313', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true),
    ('wikibooks_banana_cream_ii', 'Banana Cream II', '🍳', 'Banana cream is a milk-based dessert. It is based on Mrs Beeton''s Book of Household Management, which is public domain.', 30, 'Easy', 8, true, 'Wikibooks Cookbook', 'https://en.wikibooks.org/w/index.php?title=Cookbook%3ABanana+Cream+II&oldid=4587466', 'CC BY-SA 4.0', 'Wikibooks contributors (see linked page history)', true)
on conflict (slug) do update set
    title = excluded.title,
    emoji = excluded.emoji,
    description = excluded.description,
    total_minutes = excluded.total_minutes,
    difficulty = excluded.difficulty,
    servings = excluded.servings,
    published = excluded.published,
    source_name = excluded.source_name,
    source_url = excluded.source_url,
    license_name = excluded.license_name,
    attribution = excluded.attribution,
    modified_from_source = excluded.modified_from_source,
    updated_at = now();

