insert into public.recipe_steps (recipe_id, step_number, instruction)
select r.id, v.step_number, v.instruction
from (values
    ('wikibooks_egg_noodles_i', 1, 'In a bowl beat together eggs, salt, olive oil, and wine.'),
    ('wikibooks_egg_noodles_i', 2, 'Stir in 1 cup flour with fork.'),
    ('wikibooks_egg_noodles_i', 3, 'Gently add second cup of flour after the first is mixed thoroughly.'),
    ('wikibooks_egg_noodles_i', 4, 'Remove mixture from bowl and place on a lightly floured work surface.'),
    ('wikibooks_egg_noodles_i', 5, 'Knead in the last cup of flour a bit at a time. If the dough becomes too dry, add a bit of cold water.'),
    ('wikibooks_egg_noodles_i', 6, 'Continue kneading until the dough is uniform and shiny in appearance.'),
    ('wikibooks_egg_noodles_i', 7, 'Roll into a large ball and cut into quarters. Overturn the mixing bowl over the cut pieces to protect from dust and drying out.'),
    ('wikibooks_egg_noodles_i', 8, 'Let dough relax for approx. 30 minutes.'),
    ('wikibooks_egg_noodles_i', 9, 'Shape noodles as desired (see notes).'),
    ('wikibooks_egg_noodles_i', 10, 'To cook, bring a large pot of lightly salted water to a rolling boil. Add rolled and cut noodles to the water and cook to al dente.'),
    ('wikibooks_english_breakfast', 1, 'Heat a broiler to medium heat, and cook the sausages under it, turning frequently. They should take about 10–15 minutes total to cook.'),
    ('wikibooks_english_breakfast', 2, 'Cover the base of a frying pan with about 1cm of water, and heat on a high heat until boiling. When it is boiling, carefully break the eggs into it. If you have cooking rings, you can put these into the water first and then break the eggs into the rings, to prevent the eggs from spreading too much, although really fresh eggs should stay together anyway. Once the eggs are in the pan, wait a few moments for the water to heat up again, then turn the heat down to a very very gently simmer. To ensure the tops of the eggs are cooked, spoon water from around the edge of the pan over the top of the eggs a few times during cooking. When cooked, the egg white should be soft but cooked through and the yolk still runny. They should take about 8–10 minutes to cook.'),
    ('wikibooks_english_breakfast', 3, 'Put the halved tomatoes under the broiler with the sausages. They should take about 6 minutes to cook.'),
    ('wikibooks_english_breakfast', 4, 'If using, put the baked beans into a saucepan and heat through over a medium heat. They should take about 5 minutes to heat through.'),
    ('wikibooks_english_breakfast', 5, 'Heat up a very small amount of oil in a pan, and fry the mushrooms until they are soft. They should take about 4 minutes to cook.'),
    ('wikibooks_english_breakfast', 6, 'Put the bacon under the grill along with the sausages and tomatoes. Cook on one side for about 2 minutes, then turn once and repeat. Cook longer if crispier bacon is preferred. This should take about 4 minutes to cook.'),
    ('wikibooks_english_breakfast', 7, 'Whilst cooking the bacon, toast the bread until golden.'),
    ('wikibooks_english_breakfast', 8, 'Serve the eggs, bacon, mushrooms, sausage, tomato and beans onto piping hot plates, with the toast on a separate plate or toast rack. Serve with butter and jam for the toast, and hot tea with milk.'),
    ('wikibooks_english_breakfast', 9, 'Start toasting the bread before cooking the rest of the food. Assuming 2 slices per person, you should have enough by the time you finish the fried food. Be sure to butter them heavily with real butter rather than low-fat spread. Place 4 plates on the bottom shelf of an oven, and one on the top. Set the oven to its lowest heat.'),
    ('wikibooks_english_breakfast', 10, 'Melt some lard in a large frying pan (enough to make a layer of fat around 1 cm deep) and brown the sausage in it over a high heat. Lower heat and cook the sausage for around 4 minutes, and leave it in the pan. A lot of fat will leak from the sausages. Add the bacon (2 strips per person rather than 1) and cook to taste, flipping regularly (2–3 minutes for pink, 4–6 for a darker red bacon with crispy fat). The bacon will also release a lot of fat. Transfer the bacon to the warmed dish in the top of the oven. Leave the sausage in the pan.'),
    ('wikibooks_english_breakfast', 11, 'Add the mushrooms and tomatoes to the pan. Add the tin of baked beans to a small pot and heat on a separate burner. After 2–4 minutes, transfer the mushrooms to the oven with the bacon. Transfer the tomato then too, or leave it a little longer depending on taste.'),
    ('wikibooks_english_breakfast', 12, 'The sausages should now be dark brown, push them to the side of the pan and break an egg into the fat. Using a spatula, push hot fat over the yolk until it begins to bubble but is still liquid. This should take about 1 minute or so in a hot pan. Set out the 4 warmed plates beforehand and add an egg to each. When done, add the sausage, bacon, and mushrooms. Add the beans last. Serve with the buttered toast on a separate plate.'),
    ('wikibooks_english_breakfast', 13, 'If you are using black pudding, add it to the fat with the bacon and remove it before the eggs.'),
    ('wikibooks_english_breakfast', 14, 'If you desire a fried slice, add a slice of bread (whole or cut diagonally, in half or quarters) and allow it to absorb some of the leftover fat and lightly fry, then flip over and repeat. Alternatively, you can just fry some bread in vegetable oil in a separate pan but it doesn''t have the same flavour as bread fried in the leftover fat from cooking a full breakfast in lard. If a whole slice is used it is preferable to place the fried egg on top, so the yolk runs into the bread and can easily be absorbed by the fried slice.'),
    ('wikibooks_snails_with_garlic_butter_escargots_a_la_bourguignonne', 1, 'Preheat oven to 400°F.'),
    ('wikibooks_snails_with_garlic_butter_escargots_a_la_bourguignonne', 2, 'Drain and rinse the snails.'),
    ('wikibooks_snails_with_garlic_butter_escargots_a_la_bourguignonne', 3, 'Combine the butter with the shallots, garlic, parsley, salt, and pepper, and blend well.'),
    ('wikibooks_snails_with_garlic_butter_escargots_a_la_bourguignonne', 4, 'Sauté the mushroom caps, if using, in a small amount of garlic butter until cooked but still firm. Remove from the heat.'),
    ('wikibooks_snails_with_garlic_butter_escargots_a_la_bourguignonne', 5, 'If using snail shells, place a snail in each shell and fill the rest of the space with garlic butter. If using a snail dish without the shells, place a snail in each indentation and fill the rest of the space with garlic butter. If using mushroom caps, place 2–3 snails in each cap and top with a generous amount of garlic butter.'),
    ('wikibooks_snails_with_garlic_butter_escargots_a_la_bourguignonne', 6, 'Heat the snails in the oven for 5–7 minutes, and serve with copious quantities of French bread for soaking up the garlic butter.'),
    ('wikibooks_hongshao_rou_red_braised_pork_belly', 1, 'In a medium saucepan, over high heat, heat the oil and sugar together until the sugar melts and turns brown.'),
    ('wikibooks_hongshao_rou_red_braised_pork_belly', 2, 'Add the cubed pork to the sugar and oil and brown all over.'),
    ('wikibooks_hongshao_rou_red_braised_pork_belly', 3, 'Reduce the heat, add the stock, ginger, star anise, soy sauce, and Shaoxing wine to the pan.'),
    ('wikibooks_hongshao_rou_red_braised_pork_belly', 4, 'Cover tightly and simmer for 40 minutes, stirring occasionally to prevent it burning at the bottom.'),
    ('wikibooks_hongshao_rou_red_braised_pork_belly', 5, 'Remove the lid and add the spring onions.'),
    ('wikibooks_hongshao_rou_red_braised_pork_belly', 6, 'Boil the sauce until only a thick, dark gravy is left.'),
    ('wikibooks_hongshao_rou_red_braised_pork_belly', 7, 'The dish may be served now, but if possible, refrigerate for a day to allow the flavours to develop.'),
    ('wikibooks_hongshao_rou_red_braised_pork_belly', 8, 'Serve with rice, garnish with sliced spring onion.'),
    ('wikibooks_danwake', 1, 'Dissolve potash in a small bowl with a little water and set aside.'),
    ('wikibooks_danwake', 2, 'In a large bowl, mix wheat flour (or chosen flour) with baobab leaf flour.'),
    ('wikibooks_danwake', 3, 'Add the dissolved potash solution gradually into the flour mix.'),
    ('wikibooks_danwake', 4, 'Slowly add water while stirring until you form a thick, smooth batter.'),
    ('wikibooks_danwake', 5, 'Bring a large volume of water to a boil in a pot. Using a spoon or hand, scoop small portions of the batter and drop them into the boiling water.'),
    ('wikibooks_danwake', 6, 'Let the dumplings cook for 10–15 minutes, or until they float and are firm to the touch.'),
    ('wikibooks_danwake', 7, 'Drain the dumplings and drizzle with vegetable oil.'),
    ('wikibooks_danwake', 8, 'Garnish with chopped onions and cabbage.'),
    ('wikibooks_cauliflower_cheese', 1, 'Cut your cauliflower into small florets, and place them heads down into a bowl of salty water to dress them for an hour.'),
    ('wikibooks_cauliflower_cheese', 2, 'Drain florets, and add them to a saucepan of salted boiling water. Cook, uncovered, regularly checking the feel of the cauliflower with a knife to see when they are ready. Your knife should go smoothly, but with some firmness to the cauliflower still.'),
    ('wikibooks_cauliflower_cheese', 3, 'Preheat your oven to 200°C (180°C fan/390°F/gas 6).'),
    ('wikibooks_cauliflower_cheese', 4, 'Once the cauliflower has cooked, drain the florets and lay them in a dish of your choice. Combine the white sauce with ⅔ of the parmesan cheese, and pour over the cauliflower. Sprinkle over the breadcrumbs and remaining cheese.'),
    ('wikibooks_cauliflower_cheese', 5, 'Place your dish into the oven for about 20 minutes, or until golden brown.'),
    ('wikibooks_cauliflower_cheese', 6, 'Serve immediately.'),
    ('wikibooks_khara_pongal_rice_and_mung_bean_porridge', 1, 'Cook the rice and dhal together with turmeric powder in a pot or pressure cooker until mushy.'),
    ('wikibooks_khara_pongal_rice_and_mung_bean_porridge', 2, 'Heat a little ghee in a large pan and brown the cashew nuts. Remove them from the pan.'),
    ('wikibooks_khara_pongal_rice_and_mung_bean_porridge', 3, 'Add the rest of the ghee and the oil and heat.'),
    ('wikibooks_khara_pongal_rice_and_mung_bean_porridge', 4, 'Throw in all of the spices, starting with the mustard seed and finishing with the cashew nuts.'),
    ('wikibooks_khara_pongal_rice_and_mung_bean_porridge', 5, 'Mix in the rice and dhal, warming through. If it is too thick, add a little water.'),
    ('wikibooks_khara_pongal_rice_and_mung_bean_porridge', 6, 'Add salt and extra ghee to taste. You can also add some grated coconut at the end.'),
    ('wikibooks_ghevar_rajasthani_honeycomb_fritter', 1, 'Combine the sugar and water in a saucepan. Simmer until it reaches a 1-string consistency syrup.'),
    ('wikibooks_ghevar_rajasthani_honeycomb_fritter', 2, 'Remove from the heat and keep warm.'),
    ('wikibooks_ghevar_rajasthani_honeycomb_fritter', 3, 'Combine the flour, arrowroot, and melted ghee in a bowl.'),
    ('wikibooks_ghevar_rajasthani_honeycomb_fritter', 4, 'Very gradually add 1 cup of water in a thin stream, whisking continuously and taking care to see that an emulsion is formed and the water and ghee do not separate.'),
    ('wikibooks_ghevar_rajasthani_honeycomb_fritter', 5, 'Add 2 more cups of water again in a thin stream while whisking continuously. At no point should the ghee and water separate. The batter should be of a very thin coating consistency, a little thinner than crêpe batter. More water can be added if required to achieve the required consistency. Keep the batter in a cool place away from the heat.'),
    ('wikibooks_ghevar_rajasthani_honeycomb_fritter', 6, 'Add melted ghee to a kadhai or other pot/pan. If desired, place a ghevar mould or other metal ring mould in the pan. The ghee should come up to ¾ of the height of the mould.'),
    ('wikibooks_ghevar_rajasthani_honeycomb_fritter', 7, 'Heat the pan over medium heat, and gradually pour a ladleful of the batter directly into the centre of the mould in a very thin stream. The batter should froth and migrate towards the edges of the mold.'),
    ('wikibooks_ghevar_rajasthani_honeycomb_fritter', 8, 'When the froth subsides, gradually add another spoonful to the centre in a thin stream. If the batter builds up in the center, use a skewer to push it towards the edges and maintain a hole in the center. Repeat seven times, adding the batter to the centre hole each time.'),
    ('wikibooks_ghevar_rajasthani_honeycomb_fritter', 9, 'Increase the heat, and pour a few ladlefuls of hot ghee into the centre to help the ghevar cook.'),
    ('wikibooks_ghevar_rajasthani_honeycomb_fritter', 10, 'When the centre is firm and cooked and the whole thing is golden brown, pull the ghevar out gently by inserting a wooden skewer in the centre and pulling it out of the ghee. Let any excess ghee drip off.'),
    ('wikibooks_ghevar_rajasthani_honeycomb_fritter', 11, 'Immerse ghevar in sugar syrup, drain quickly, and place on a serving plate.'),
    ('wikibooks_ghevar_rajasthani_honeycomb_fritter', 12, 'Repeat the cooking steps, using the remaining batter to make 9 pieces of ghevar.'),
    ('wikibooks_chicken_bacon_broccoli_alfredo_spaghetti', 1, 'Boil the spaghetti in water until al dente.'),
    ('wikibooks_chicken_bacon_broccoli_alfredo_spaghetti', 2, 'Meanwhile, heat the oil in a pan over a medium heat.'),
    ('wikibooks_chicken_bacon_broccoli_alfredo_spaghetti', 3, 'Cook the chicken in oil for 4 minutes until cooked.'),
    ('wikibooks_chicken_bacon_broccoli_alfredo_spaghetti', 4, 'Add in salt, pepper, and garlic, and stir.'),
    ('wikibooks_chicken_bacon_broccoli_alfredo_spaghetti', 5, 'Stir in broccoli, then add milk and cook for 3 minutes, stirring occasionally.'),
    ('wikibooks_chicken_bacon_broccoli_alfredo_spaghetti', 6, 'Stir in cheese, parsley and bacon.'),
    ('wikibooks_chicken_bacon_broccoli_alfredo_spaghetti', 7, 'Drain the pasta in a colander and stir into the chicken sauce.'),
    ('wikibooks_chicken_bacon_broccoli_alfredo_spaghetti', 8, 'Divide the pasta between 4 plates and serve.'),
    ('wikibooks_beanburger', 1, 'Fry the onions and pepper (in a little bit of oil) with the spices for a couple of minutes. Leave to cool.'),
    ('wikibooks_beanburger', 2, 'Mash the beans in a large bowl.'),
    ('wikibooks_beanburger', 3, 'Add the carrot, onion, pepper and oats to the mashed beans and mix until well combined.'),
    ('wikibooks_beanburger', 4, 'Add the egg gradually (you probably won''t need all of it). You don''t want a mixture that''s too sticky.'),
    ('wikibooks_beanburger', 5, 'Shape the dough into 6 to 8 burgers and lightly flour each side.'),
    ('wikibooks_beanburger', 6, 'Fry the burgers (in a little bit of oil) for a few minutes on each side, until golden.'),
    ('wikibooks_beanburger', 7, 'Serve hot.'),
    ('wikibooks_hamburger_fried_rice', 1, 'Heat the canola oil in a non-stick frying pan. When the oil is very hot, fry the garlic, red onion, ginger, and red chillies. Stir every 20 seconds until fragrant.'),
    ('wikibooks_hamburger_fried_rice', 2, 'Add the hamburger meat, and cook until the meat browns and is cooked through.'),
    ('wikibooks_hamburger_fried_rice', 3, 'Add the celery and scallion. Add the rice, salt, black pepper, and black soy sauce. Cook until well mixed and heated through.'),
    ('wikibooks_hamburger_fried_rice', 4, 'Serve hot.'),
    ('wikibooks_baked_ziti', 1, 'Preheat oven to 425 °F (225 °C). Coat a large baking dish with olive oil.'),
    ('wikibooks_baked_ziti', 2, 'Mix ricotta, egg, basil, oregano, parsley and about half of the mozzarella and Parmesan in a large bowl until well incorporated. Season with salt and pepper.'),
    ('wikibooks_baked_ziti', 3, 'Cook ziti in a large pot of salted water until al dente. Drain well.'),
    ('wikibooks_baked_ziti', 4, 'In a large bowl or pot, toss ziti with marinara sauce and red pepper flakes until noodles are covered. Stir in ricotta mixture and fold until it begins to melt. Pour mixture into greased dish and spread it out with a spoon.'),
    ('wikibooks_baked_ziti', 5, 'Sprinkle remaining mozzarella and Parmesan over the top, then sprinkle bread crumbs over cheese.'),
    ('wikibooks_baked_ziti', 6, 'Bake at 425 °F (225 °C) for 20 minutes or until cheese on top turns golden and begins to bubble.'),
    ('wikibooks_crab_fried_rice', 1, 'Stir fry the crab in the 5 tbsp oil for 1 minute. Remove from the heat, and reserve.'),
    ('wikibooks_crab_fried_rice', 2, 'Heat the remaining oil, and use to stir fry the garlic, red onion, scallion, and red chillies for 1 minute until fragrant.'),
    ('wikibooks_crab_fried_rice', 3, 'Add the fried crab and bean sprouts. Stir until the crab changes color.'),
    ('wikibooks_crab_fried_rice', 4, 'Add the rice, fish sauce, salt, and black pepper. Stir until well-mixed.'),
    ('wikibooks_crab_fried_rice', 5, 'Serve hot.'),
    ('wikibooks_banana_cream_ii', 1, 'Mix the cornstarch smoothly with a little milk to form a paste.'),
    ('wikibooks_banana_cream_ii', 2, 'Put the remaining milk into a pan with the sugar. When boiling add the cornstarch paste, and boil for about 10 minutes.'),
    ('wikibooks_banana_cream_ii', 3, 'Let the mixture cool a little, then add the beaten egg yolks, and stir until they thicken.'),
    ('wikibooks_banana_cream_ii', 4, 'Add the vanilla, the bananas. When cool, pour into the prepared mould.'),
    ('wikibooks_banana_cream_ii', 5, 'Chill for a few hours to set.')
) as v(recipe_slug, step_number, instruction)
join public.recipes r on r.slug = v.recipe_slug;

